    cfg = {
        "users": [{
            "sftpuser": "alice",
            "sambaVault": True,
            "sftpmounts": {"docs": "/srv/old"},
            "pointsSet": {"docs": {"rw": False}},
        }]
    }
    main_menu = SimpleNamespace(cfg=cfg, changed=False)
    submenu = sftp_menu.m_user_mountpoints("alice", main_menu, cfg["users"][0])
